/// Uses IMemoryCache with sliding expiration.
/// </summary>
public async Task<Consumer17Data> GetCachedConsumer17Async(string key)
{
    var cacheKey = $"Consumer17_{key}";

    if (_cache.TryGetValue(cacheKey, out Consumer17Data cached))
